package com.nextstep.service;
import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import org.apache.pdfbox.Loader;import org.apache.pdfbox.text.PDFTextStripper;import org.apache.poi.xwpf.usermodel.*;import java.util.*;import java.io.*;import com.nextstep.web.Errors;
@Service public class ResumeService {
 public static final List<String> SKILLS=List.of("java","python","javascript","typescript","react","html","css","sql","postgresql","mysql","docker","git","aws","azure","excel","tableau","power bi","pandas","numpy","spring","c++","linux","machine learning");
 public Map<String,Object> analyze(MultipartFile file,String targetRole,String job){if(file.isEmpty()||file.getSize()>5*1024*1024)throw Errors.bad("Upload a PDF or DOCX under 5 MB.");String name=Objects.toString(file.getOriginalFilename(),"").toLowerCase(Locale.ROOT);String text;int pages=0;try{if(name.endsWith(".pdf")){try(var pdf=Loader.loadPDF(file.getBytes())){pages=pdf.getNumberOfPages();if(pages>20)throw Errors.bad("Maximum 20 pages.");text=new PDFTextStripper().getText(pdf);}}else if(name.endsWith(".docx")){try(var doc=new XWPFDocument(file.getInputStream())){var out=new StringBuilder();doc.getParagraphs().forEach(p->out.append(p.getText()).append('\n'));doc.getTables().forEach(t->t.getRows().forEach(r->r.getTableCells().forEach(c->out.append(c.getText()).append('\n'))));text=out.toString();}}else throw Errors.bad("Only PDF and DOCX are supported.");}catch(IOException|org.apache.poi.openxml4j.exceptions.OLE2NotOfficeXmlFileException e){throw Errors.bad("Unable to read this document. Use an unencrypted PDF or DOCX.");}if(text.isBlank())throw Errors.bad("No readable text found. Scanned images require OCR, which is not configured.");if(text.length()>200000)throw Errors.bad("Document text exceeds the analysis limit.");return analyzeText(text,targetRole,job,pages);}
 public Map<String,Object> analyzeText(String text,String role,String job,int pages){String lower=text.toLowerCase(Locale.ROOT);var checks=new LinkedHashMap<String,Boolean>();checks.put("Email address",lower.matches("(?s).*[a-z0-9._%+-]+@[a-z0-9.-]+\\.[a-z]{2,}.*"));checks.put("Phone number",lower.replaceAll("[() +\\s-]","").matches("(?s).*\\d{10,}.*"));checks.put("Education section",lower.matches("(?s).*(education|university|degree|bachelor).*"));checks.put("Skills section",lower.contains("skills"));checks.put("Projects section",lower.contains("project"));checks.put("Experience or internships",lower.matches("(?s).*(experience|internship).*"));checks.put("Professional profile link",lower.contains("github")||lower.contains("linkedin"));checks.put("Measurable outcomes",lower.matches("(?s).*\\d+%.*"));var found=SKILLS.stream().filter(lower::contains).toList();String jobLower=job.toLowerCase(Locale.ROOT);var wanted=job.isBlank()?switch(role){case "Data Analyst"->List.of("sql","excel","python");case "Frontend Developer"->List.of("javascript","react","css");case "Java Developer"->List.of("java","spring","sql");default->List.of("git","sql");}:SKILLS.stream().filter(jobLower::contains).toList();var missing=wanted.stream().filter(s->!found.contains(s)).toList();var suggestions=new ArrayList<String>();checks.forEach((k,v)->{if(!v)suggestions.add("Consider adding: "+k+".");});if(pages>2)suggestions.add("Consider a concise one- or two-page resume for fresher roles.");if(text.split("\\s+").length>1000)suggestions.add("Shorten dense sections and prioritize relevant achievements.");if(lower.contains("responsible for"))suggestions.add("Replace 'responsible for' with a specific action and outcome.");suggestions.add("Proofread tense, spelling and punctuation. Automated grammar analysis is not configured.");suggestions.add("Use clear section headings and selectable text; manually check columns, tables and reading order.");return Map.of("score",Math.round(checks.values().stream().filter(value -> Boolean.TRUE.equals(value)).count()*100f/checks.size()),"checks",checks,"skills",found,"missingSkills",missing,"matchPercent",wanted.isEmpty()?0:Math.round((wanted.size()-missing.size())*100f/wanted.size()),"suggestions",suggestions,"wordCount",text.trim().split("\\s+").length,"method","Completeness = detected checks / 8 × 100. Skill matching uses a fixed keyword list. This is not AI analysis or an ATS compatibility score.");}
}
